#!/usr/bin/env bash
# Generated by Cloudhop. Entry point on GitLab CI, Bitbucket Pipelines and Azure Pipelines:
# installs the tools, exchanges the CI's OIDC token for short-lived cloud access, then runs run.sh.
# Expects CLOUDHOP_OIDC_TOKEN, CLOUDHOP_ACTION, CLOUDHOP_CLOUD and optionally CLOUDHOP_SOURCE.
set -euo pipefail

SUDO="$(command -v sudo || true)"
need() { command -v "$1" >/dev/null 2>&1; }
export DEBIAN_FRONTEND=noninteractive

if ! need jq || ! need curl || ! need unzip || ! need git || ! need ssh || ! need gpg; then
  $SUDO apt-get update -qq
  $SUDO apt-get install -y -qq jq curl unzip git openssh-client ca-certificates gnupg >/dev/null
fi
cfg() { jq -r "$1" .cloudhop/config.json; }
HAS_AWS="$(cfg '.clouds.aws != null')"
HAS_GCP="$(cfg '.clouds.gcp != null')"

# OpenTofu from its signed apt repository.
if ! need tofu; then
  curl -fsSL https://get.opentofu.org/install-opentofu.sh -o /tmp/install-opentofu.sh
  $SUDO bash /tmp/install-opentofu.sh --install-method deb >/dev/null
fi
if [ "$HAS_AWS" = true ] && ! need aws; then
  curl -fsSL https://awscli.amazonaws.com/awscli-exe-linux-x86_64.zip -o /tmp/awscli.zip
  unzip -q /tmp/awscli.zip -d /tmp && $SUDO /tmp/aws/install >/dev/null
fi
if [ "$HAS_GCP" = true ] && ! need gcloud; then
  curl -fsSL https://packages.cloud.google.com/apt/doc/apt-key.gpg | $SUDO gpg --dearmor -o /usr/share/keyrings/cloud.google.gpg
  echo "deb [signed-by=/usr/share/keyrings/cloud.google.gpg] https://packages.cloud.google.com/apt cloud-sdk main" | $SUDO tee /etc/apt/sources.list.d/google-cloud-sdk.list >/dev/null
  $SUDO apt-get update -qq && $SUDO apt-get install -y -qq google-cloud-cli >/dev/null
fi

# Keyless cloud access: both clouds trust this CI's OIDC token for this repo only.
[ -n "${CLOUDHOP_OIDC_TOKEN:-}" ] || { echo "No OIDC token from the CI. See the Cloudhop setup steps for this provider." >&2; exit 1; }
TOKEN_FILE="$(mktemp)"
printf '%s' "$CLOUDHOP_OIDC_TOKEN" > "$TOKEN_FILE"
if [ "$HAS_AWS" = true ]; then
  AWS_ROLE_ARN="$(cfg .clouds.aws.roleArn)"
  AWS_REGION="$(cfg .clouds.aws.region)"
  export AWS_ROLE_ARN AWS_REGION AWS_DEFAULT_REGION="$AWS_REGION" AWS_WEB_IDENTITY_TOKEN_FILE="$TOKEN_FILE" AWS_ROLE_SESSION_NAME=cloudhop
fi
if [ "$HAS_GCP" = true ]; then
  CREDS="$(mktemp)"
  gcloud iam workload-identity-pools create-cred-config "$(cfg .clouds.gcp.workloadIdentityProvider)" \
    --service-account="$(cfg .clouds.gcp.serviceAccount)" --credential-source-file="$TOKEN_FILE" --output-file="$CREDS" --quiet
  gcloud auth login --cred-file="$CREDS" --quiet
  export GOOGLE_APPLICATION_CREDENTIALS="$CREDS"
fi

exec bash .cloudhop/run.sh "$CLOUDHOP_ACTION" "$CLOUDHOP_CLOUD" "${CLOUDHOP_SOURCE:-}"
